import{_ as e,o,c as a,ag as r}from"./chunks/framework.By9v0nLp.js";const p=JSON.parse('{"title":"Players","description":"","frontmatter":{},"headers":[],"relativePath":"for-players.md","filePath":"for-players.md"}'),n={name:"for-players.md"};function s(d,t,i,c,h,l){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="players" tabindex="-1">Players <a class="header-anchor" href="#players" aria-label="Permalink to &quot;Players&quot;">​</a></h1><p>What to expect when an NPC talks to you.</p><h2 id="how-a-conversation-works" tabindex="-1">How a conversation works <a class="header-anchor" href="#how-a-conversation-works" aria-label="Permalink to &quot;How a conversation works&quot;">​</a></h2><p>A box opens at the bottom of the screen. The speaker&#39;s name sits on top of it, their portrait on the left, and their words type out one letter at a time with a little talking sound.</p><p>When a line finishes, a small arrow blinks in the corner. Press a key to continue. When the character asks you something, a list of answers appears above the box with a red heart next to the one you&#39;re pointing at.</p><p>The game keeps running while you talk. Nothing pauses, so pick a safe spot to chat.</p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Z</strong>, <strong>Enter</strong>, <strong>Space</strong> or <strong>left click</strong></td><td>Continue to the next box, or pick the answer the heart is on</td></tr><tr><td><strong>X</strong> or <strong>Shift</strong></td><td>Show the rest of the line straight away</td></tr><tr><td><strong>Arrow keys</strong>, <strong>W / S</strong> or <strong>mouse wheel</strong></td><td>Move between answers</td></tr><tr><td><strong>Mouse</strong></td><td>Point at an answer and click it</td></tr><tr><td><strong>Esc</strong></td><td>Leave the conversation (some conversations don&#39;t allow this)</td></tr></tbody></table><h2 id="greyed-out-answers" tabindex="-1">Greyed-out answers <a class="header-anchor" href="#greyed-out-answers" aria-label="Permalink to &quot;Greyed-out answers&quot;">​</a></h2><p>Some answers show up in grey with a note after them, such as <em>I brought you some apples. (needs 3 apples)</em>. You can&#39;t pick those yet. The note tells you what&#39;s missing, so you can come back later.</p><p>Other answers stay hidden entirely until you&#39;ve done something, so it&#39;s worth talking to characters again.</p><h2 id="npcs-remember-you" tabindex="-1">NPCs remember you <a class="header-anchor" href="#npcs-remember-you" aria-label="Permalink to &quot;NPCs remember you&quot;">​</a></h2><p>Characters can remember what you said and did: whether you&#39;ve met, whether you helped them, how much they like you. Their greetings and answers change over time. If you leave a conversation early with <strong>Esc</strong>, it doesn&#39;t count as finished, so you can usually pick up where you left off.</p><h2 id="talking-to-an-npc" tabindex="-1">Talking to an NPC <a class="header-anchor" href="#talking-to-an-npc" aria-label="Permalink to &quot;Talking to an NPC&quot;">​</a></h2><p>Right-click a character that has something to say. They turn to face you while you talk. If you walk more than 8 blocks away, the conversation ends.</p><h2 id="your-own-settings" tabindex="-1">Your own settings <a class="header-anchor" href="#your-own-settings" aria-label="Permalink to &quot;Your own settings&quot;">​</a></h2><p>Open <code>config/nostalgicdialog-client.toml</code> to change how conversations feel on your screen. Changes apply the next time a conversation opens.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it changes</th></tr></thead><tbody><tr><td><code>text_speed</code></td><td><code>1.5</code></td><td>Letters typed per tick (20 ticks = 1 second). Higher is faster. Range 0.1 to 20</td></tr><tr><td><code>sentence_pause</code></td><td><code>6</code></td><td>Short wait after <code>.</code> <code>!</code> <code>?</code>, in ticks. <code>0</code> turns it off</td></tr><tr><td><code>comma_pause</code></td><td><code>3</code></td><td>Short wait after <code>,</code> <code>;</code> <code>:</code>, in ticks</td></tr><tr><td><code>voice_volume</code></td><td><code>1.0</code></td><td>Volume of the talking sounds. <code>0</code> mutes them. Range 0 to 2</td></tr><tr><td><code>confirm_reveals</code></td><td><code>true</code></td><td>If <code>true</code>, the continue key also finishes a line that&#39;s still typing. If <code>false</code>, only X / Shift does</td></tr><tr><td><code>text_scale</code></td><td><code>1.0</code></td><td>Text size. Range 0.5 to 3</td></tr><tr><td><code>box_width</code></td><td><code>360</code></td><td>Widest the box can get, in GUI pixels. It shrinks on small windows</td></tr></tbody></table>',18)])])}const g=e(n,[["render",s]]);export{p as __pageData,g as default};
